    function googleGrowthSitemapXml(){
      const esc=v=>String(v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;").replace(/'/g,"&apos;");
      return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+SEO_ALL_INDEXABLE_ROUTES.map(p=>'<url><loc>'+esc(GOOGLE_GROWTH_ARCHITECTURE.canonicalOrigin+p)+'</loc></url>').join('')+'</urlset>';
    }
