    function modulePage(title, description) {
      return `<!doctype html>
    <html lang="tr">
    <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>${escapeHTML(title)} | Okyanus EDT</title>

    <style>
    *{box-sizing:border-box;text-shadow:none!important}
    body{
      margin:0;
      min-height:100vh;
      display:grid;
      place-items:center;
      padding:24px;
      font-family:Arial,Helvetica,sans-serif;
      color:#fff;
      background:
        radial-gradient(circle at 80% 10%,rgba(67,183,226,.22),transparent 30%),
        linear-gradient(145deg,#04152d,#0b3c67);
    }
    .box{
      width:min(850px,100%);
      padding:50px;
      border:1px solid rgba(255,255,255,.14);
      border-radius:30px;
      background:rgba(255,255,255,.06);
    }
    small{
      color:#72ccea;
      font-weight:900;
      letter-spacing:1.4px;
    }
    h1{
      margin:15px 0;
      font-size:clamp(42px,8vw,78px);
      letter-spacing:-3px;
    }
    p{
      max-width:650px;
      color:#c5d9e8;
      font-size:17px;
      line-height:1.75;
    }
    a{
      display:inline-flex;
      margin-top:20px;
      padding:15px 20px;
      border-radius:12px;
      background:#fff;
      color:#061831;
      text-decoration:none;
      font-weight:900;
    }
    </style>
    </head>

    <body>
    <main class="box">
      <small>OKYANUS EDT \u2022 PROFESYONEL \u00c7ALI\u015eMA ALANI</small>
      <h1>${escapeHTML(title)}</h1>
      <p>${escapeHTML(description)}</p>
      <a href="/">\u2190 Ana Sayfaya D\u00f6n</a>
    </main>
    </body>
    </html>`;
    }


