    function safeVitrineUrl(v){try{const u=new URL(String(v||''));return u.protocol==='https:'?u.href:''}catch{return ''}}

    /* OKYANUS VITRIN LIVE HYDRATION v1.1
       D1/API do\u011fru olsa bile eski HTML/SW g\u00f6r\u00fcnt\u00fcs\u00fcn\u00fc ezerek aktif yay\u0131n\u0131 ekrana getirir. */
    function vitrineLiveHydrationScript(){
      return `<script id="oky-vitrine-live-v13">
    (()=>{const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const safe=v=>{try{const u=new URL(String(v||''),location.origin);return u.protocol==='https:'?u.href:''}catch(_){return''}};
    function ensureTarget(){
     let section=document.getElementById('okyanus-vitrini');
     if(section)return section;
     const old=document.querySelector('.digitalMenuHero');
     section=document.createElement('section');
     section.id='okyanus-vitrini';section.className='okyVitrine';
     if(old){old.replaceWith(section);return section}
     const lower=document.querySelector('section.lower');
     if(lower&&lower.parentNode){lower.parentNode.insertBefore(section,lower);return section}
     const main=document.querySelector('main');if(main){main.appendChild(section);return section}
     return null;
    }
    async function refreshVitrine(){
     try{
      const r=await fetch('/api/vitrine?ts='+Date.now(),{cache:'no-store',headers:{accept:'application/json','cache-control':'no-cache'}});
      if(!r.ok)throw Error('VITRINE_API_'+r.status);
      const j=await r.json(),d=j&&j.ok?j.data:null,p=d&&d.payload||{},scenes=Array.isArray(p.scenes)?p.scenes.slice(0,8):[];
      const section=ensureTarget();if(!section)return;
      if(!d||!scenes.length){
        section.innerHTML='<div class="okyVHead"><small>OKYANUS EDT</small><h2>Okyanus Vitrini</h2></div><div class="okyVEmpty"><b>Okyanus Vitrini</b><span>Yeni i\u00e7erik haz\u0131rlan\u0131yor.</span></div>';
        section.dataset.publishedAt='';
        return;
      }
      const cards=scenes.map(s=>{const url=safe(s.url);let media='';
       if(url)media=s.type==='video'?'<video controls playsinline preload="metadata" src="'+esc(url)+'"></video>':'<img loading="eager" src="'+esc(url)+'" alt="'+esc(s.headline||d.title||'Okyanus EDT')+'">';
       return '<article class="okyVCard">'+media+'<div><h3>'+esc(s.headline||d.title||'Okyanus EDT')+'</h3><p>'+esc(s.text||'')+'</p>'+(s.cta?'<span class="okyVCTA">'+esc(s.cta)+'</span>':'')+'</div></article>';
      }).join('');
      section.innerHTML='<div class="okyVHead"><small>OKYANUS EDT</small><h2>Okyanus Vitrini</h2></div><div class="okyVGrid">'+cards+'</div>';
      section.dataset.publishedAt=String(d.publishedAt||'');
     }catch(e){console.warn('VITRINE_LIVE_REFRESH',e)}
    }
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',refreshVitrine,{once:true});else refreshVitrine();
    addEventListener('pageshow',refreshVitrine);
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshVitrine()});
    })();
    </script>`;
    }
