    function cesniMethodKey(m){
      const t=String((m&&m.name)||m||"").toLocaleLowerCase("tr-TR");
      if(t.includes("kabayaki"))return"KABAYAKI";
      if(t.includes("shioyaki"))return"SHIOYAKI";
      if(t.includes("nitsuke"))return"NITSUKE";
      if(t.includes("tataki"))return"TATAKI";
      if(t.includes("aburi")||t.includes("alevle"))return"TORCH";
      if(t.includes("tempura"))return"TEMPURA";
      if(t.includes("nanbanzuke")||t.includes("escabeche"))return"ESCABECHE";
      if(t.includes("ceviche"))return"CEVICHE";
      if(t.includes("wok")||t.includes("stir-fry")||t.includes("stir fry"))return"WOK";
      if(t.includes("salamander")||t.includes("broil")||t.includes("\u00fcstten \u0131zgara"))return"BROIL";
      if(t.includes("pane")||t.includes("breaded"))return"BREADED_FRY";
      if(t.includes("bas\u0131n\u00e7")||t.includes("pressure"))return"PRESSURE";
      if(t.includes("clay pot")||t.includes("toprak kap"))return"CLAY_POT";
      if(t.includes("ishiyaki")||t.includes("s\u0131cak ta\u015f"))return"HOT_STONE";
      if(t.includes("blan\u015f")||t.includes("blanch"))return"BLANCH";
      if(t.includes("sous"))return"SOUS_VIDE";
      if(t.includes("d\u00fc\u015f\u00fck")||t.includes("low temp"))return"LOW_TEMP";
      if(t.includes("\u00e7in")&&t.includes("buhar"))return"CHINESE_STEAM";
      if(t.includes("papillote")||t.includes("ka\u011f\u0131t"))return"PAPILLOTE";
      if(t.includes("tuz kab")||t.includes("salt crust"))return"SALT_CRUST";
      if(t.includes("rotisserie")||t.includes("\u015fi\u015f")||t.includes("spit"))return"SPIT_ROAST";
      if(t.includes("tand\u0131r")||t.includes("tandoor"))return"TANDOOR";
      if(t.includes("plancha")||t.includes("sac"))return"PLANCHA";
      if(t.includes("t\u00fcts")||t.includes("smok"))return"SMOKE";
      if(t.includes("konfi")||t.includes("confit"))return"CONFIT";
      if(t.includes("po\u015fe")||t.includes("poach")||t.includes("nizakana"))return"POACH";
      if(t.includes("simmer")||t.includes("k\u0131s\u0131k"))return"SIMMER";
      if(t.includes("g\u00fcve\u00e7")||t.includes("yahni")||t.includes("stew")||t.includes("moqueca"))return"STEW";
      if(t.includes("braise")||t.includes("a\u011f\u0131r"))return"BRAISE";
      if(t.includes("sote")||t.includes("saut\u00e9"))return"SAUTE";
      if(t.includes("m\u00fch\u00fcr")||t.includes("sear"))return"SEAR";
      if(t.includes("s\u0131\u011f")&&t.includes("k\u0131zart"))return"SHALLOW_FRY";
      if(t.includes("k\u0131zart")||t.includes("deep-fry")||t.includes("deep fry"))return"FRY";
      if(t.includes("\u0131zgara")||t.includes("grill"))return"GRILL";
      if(t.includes("roast")||t.includes("f\u0131r\u0131nda k\u0131z"))return"ROAST";
      if(t.includes("f\u0131r\u0131n")||t.includes("oven")||t.includes("bake"))return"OVEN";
      if(t.includes("buhar")||t.includes("steam"))return"STEAM";
      if(t.includes("tava")||t.includes("pan-fry")||t.includes("pan fry"))return"PAN";
      if(t.includes("ha\u015f")||t.includes("boil"))return"BOIL";
      if(t.includes("graten")||t.includes("gratin"))return"GRATIN";
      if(t.includes("rejener")||t.includes("finishing")||t.includes("reheat"))return"REGENERATE";
      if(t.includes("k\u00fcr")||t.includes("cure")||t.includes("tuzlama"))return"CURE";
      if(t.includes("pickle")||t.includes("asitle"))return"PICKLE";
      if(t.includes("marine")||t.includes("marinasyon"))return"MARINATE";
      return null;
    }
