      const methodsByProduct=new Map();
      const recipesByProduct=new Map(),recipesByProductMethod=new Map(),recipesByProductMasterMethod=new Map();
      const norm=s=>String(s||"").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9\u00e7\u011f\u0131\u00f6\u015f\u00fc]+/g," ").trim();
