      for(const m of core.productMethods){if(!methodsByProduct.has(m.productId))methodsByProduct.set(m.productId,[]);methodsByProduct.get(m.productId).push(m)}
      for(const r of core.recipes){
        if(!recipesByProduct.has(r.productId))recipesByProduct.set(r.productId,[]);recipesByProduct.get(r.productId).push(r);
        const methods=methodsByProduct.get(r.productId)||[];
        // v2.6: Kaynak re\u00e7etede sourceMethodName varsa bu alan birincil kan\u0131tt\u0131r. Ba\u015fl\u0131k/profil yaln\u0131z
        // ikincil do\u011frulama i\u00e7indir. B\u00f6ylece "Izgara" kayd\u0131 "\u0131zgara" kaynak y\u00f6ntemiyle do\u011frudan ba\u011flan\u0131r.
        const sourceMethodText=norm(r.sourceMethodName||"");
        const recipeText=norm((r.title||"")+" "+(r.profile||"")+" "+(r.raw||""));
        let hit=null, linkStatus="METHOD_RESEARCH_REQUIRED";
        if(sourceMethodText){
          const exact=methods.filter(m=>norm(m.name)===sourceMethodText);
          if(exact.length===1){hit=exact[0];linkStatus="SOURCE_METHOD_EXACT";}
          else {
            const sourceMaster=cesniMethodKey(r.sourceMethodName||"");
            const masterHits=sourceMaster?methods.filter(m=>cesniMethodKey(m)===sourceMaster):[];
            if(masterHits.length===1){hit=masterHits[0];linkStatus="SOURCE_METHOD_MASTER";}
            else if(masterHits.length>1)linkStatus="AMBIGUOUS_SOURCE_METHOD";
          }
        }
        if(!hit){
          const titleMaster=cesniMethodKey(r.title||"");
          const titleHits=titleMaster?methods.filter(m=>cesniMethodKey(m)===titleMaster):[];
          if(titleHits.length===1){hit=titleHits[0];linkStatus="TITLE_METHOD_MASTER";}
          else if(titleHits.length>1)linkStatus="AMBIGUOUS_TITLE_METHOD";
        }
        if(!hit){
          const textHits=methods.filter(m=>{const mn=norm(m.name);return mn&&recipeText.includes(mn)});
          if(textHits.length===1){hit=textHits[0];linkStatus="TEXT_METHOD_MATCH";}
          else if(textHits.length>1)linkStatus="AMBIGUOUS_METHOD";
        }
        if(hit){
          r.methodId=hit.methodId;
          r.methodMasterId=cesniMethodKey(hit)||null;
          r.methodLinkStatus=linkStatus;
          const k=r.productId+"|"+hit.methodId;if(!recipesByProductMethod.has(k))recipesByProductMethod.set(k,[]);recipesByProductMethod.get(k).push(r);
          if(r.methodMasterId){const mk=r.productId+"|"+r.methodMasterId;if(!recipesByProductMasterMethod.has(mk))recipesByProductMasterMethod.set(mk,[]);recipesByProductMasterMethod.get(mk).push(r)}
        } else {r.methodId=null;r.methodMasterId=null;r.methodLinkStatus=linkStatus}
      }
