    function b64Bytes(s){const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
    async function cesniSourceText(key){const b64=CESNI_SOURCE_GZIP_B64[key];if(!b64)return null;const stream=new Blob([b64Bytes(b64)]).stream().pipeThrough(new DecompressionStream("gzip"));return await new Response(stream).text()}
    async function cesniSourceApi(url){
      const key=String(url.searchParams.get("key")||"").toLowerCase();
      if(!key)return responseJSON({ok:true,version:APP_VERSION,cesniVersion:CESNI_VERSION,masterWrite:false,engineeringDecisions:CESNI_ENGINEERING_DECISIONS,researchSources:CESNI_RESEARCH_REGISTRY,sources:CESNI_SOURCE_MANIFEST});
      if(!CESNI_SOURCE_GZIP_B64[key])return responseJSON({ok:false,error:"SOURCE_NOT_FOUND",allowed:Object.keys(CESNI_SOURCE_MANIFEST)},404);
      const text=await cesniSourceText(key);
      const q=String(url.searchParams.get("q")||"").trim().toLocaleLowerCase("tr-TR");
      if(!q)return new Response(text,{status:200,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"public, max-age=3600","x-robots-tag":"noindex"}});
      const lines=text.split(/\r?\n/),hits=[];
      for(let i=0;i<lines.length&&hits.length<80;i++){if(lines[i].toLocaleLowerCase("tr-TR").includes(q))hits.push({line:i+1,text:lines[i].trim()})}
      return responseJSON({ok:true,key,q,count:hits.length,hits,masterWrite:false});
    }

    const PROFIT_RADAR_V5160 = Object.freeze({
      release:"5.16.0",
      fingerprint:"PROFIT_RADAR_EXPLAINABLE_V5160",
      maxMonthly:1000000000,
      types:{
        RESTORAN:{label:"Restoran",purchaseGuide:.34,fixedGuide:.30},
        KAFE:{label:"Kafe",purchaseGuide:.32,fixedGuide:.33},
        OTEL:{label:"Otel",purchaseGuide:.36,fixedGuide:.34},
        CATERING:{label:"Catering / Yemekhane",purchaseGuide:.38,fixedGuide:.28},
        DIGER:{label:"Di\u011fer HORECA",purchaseGuide:.35,fixedGuide:.32}
      }
    });
    function radarNumber(v){if(typeof v==="number")return Number.isFinite(v)?v:0;let s=String(v??"").trim().replace(/\s/g,"");if(s.includes(","))s=s.replace(/\./g,"").replace(",",".");else if(/^[+-]?\d{1,3}(?:\.\d{3})+$/.test(s))s=s.replace(/\./g,"");const n=Number(s);return Number.isFinite(n)?n:0}
    function radarRound(n){return Math.round((Number(n)||0)*100)/100}
    function radarType(v){const k=String(v||"").trim().toLocaleUpperCase("tr-TR");return PROFIT_RADAR_V5160.types[k]?k:"DIGER"}
    function radarId(){return "PR-"+crypto.randomUUID().slice(0,8).toUpperCase()}
    function calculateProfitRadarV5160(p={}){
      const revenue=radarNumber(p.monthlyRevenue),purchase=radarNumber(p.monthlyPurchase),fixed=radarNumber(p.monthlyFixed);
      if(revenue<=0)throw new Error("Ayl\u0131k ciro s\u0131f\u0131rdan b\u00fcy\u00fck olmal\u0131d\u0131r.");
      if(purchase<0||fixed<0)throw new Error("Giderler negatif olamaz.");
      if(revenue>PROFIT_RADAR_V5160.maxMonthly||purchase>PROFIT_RADAR_V5160.maxMonthly||fixed>PROFIT_RADAR_V5160.maxMonthly)throw new Error("Girilen tutar izin verilen analiz s\u0131n\u0131r\u0131n\u0131 a\u015f\u0131yor.");
      if(purchase+fixed>revenue*3)throw new Error("Rakamlar\u0131 kontrol edin; gider toplam\u0131 cironun \u00fc\u00e7 kat\u0131n\u0131 a\u015f\u0131yor.");
      const typeKey=radarType(p.businessType),guide=PROFIT_RADAR_V5160.types[typeKey];
      const purchaseRatio=purchase/revenue,fixedRatio=fixed/revenue,totalRatio=(purchase+fixed)/revenue;
      const purchaseExcess=Math.max(0,purchaseRatio-guide.purchaseGuide),fixedExcess=Math.max(0,fixedRatio-guide.fixedGuide);
      let purchasingOpportunity=Math.min(purchase*.035,revenue*Math.min(.010,Math.max(.0025,purchaseExcess*.18)));
      if(purchaseRatio<=guide.purchaseGuide)purchasingOpportunity=purchase*.005;
      let operationOpportunity=Math.min(fixed*.015,revenue*Math.min(.004,Math.max(.001,fixedExcess*.08)));
      if(fixedRatio<=guide.fixedGuide)operationOpportunity=fixed*.0025;
      const monthlyMid=Math.max(0,purchasingOpportunity+operationOpportunity);
      const annualMid=Math.min(monthlyMid*12,revenue*12*.015),annualLow=annualMid*.55,annualHigh=annualMid*1.35;
      let opportunities=[];
      if(purchaseRatio>guide.purchaseGuide)opportunities.push({code:"PURCHASE",title:"Sat\u0131n alma optimizasyonu",level:purchaseRatio>guide.purchaseGuide+.08?"Y\u00dcKSEK":"ORTA",detail:"Sat\u0131n alma oran\u0131n\u0131z \u00f6n analiz rehberinin \u00fczerinde g\u00f6r\u00fcn\u00fcyor. Tedarik, gramaj ve fiyat kar\u015f\u0131la\u015ft\u0131rmas\u0131 \u00f6nerilir."});
      else opportunities.push({code:"PURCHASE_CONTROL",title:"Sat\u0131n alma kontrol\u00fc",level:"D\u00dc\u015e\u00dcK",detail:"Sat\u0131n alma oran\u0131n\u0131z kontroll\u00fc g\u00f6r\u00fcn\u00fcyor; \u00fcr\u00fcn baz\u0131nda do\u011frulama yine de fayda sa\u011flayabilir."});
      if(fixedRatio>guide.fixedGuide)opportunities.push({code:"FIXED",title:"Sabit gider y\u00fck\u00fc",level:fixedRatio>guide.fixedGuide+.08?"Y\u00dcKSEK":"ORTA",detail:"Sabit giderlerin ciro i\u00e7indeki pay\u0131 dikkat gerektiriyor. Sat\u0131\u015f ba\u015f\u0131na gider da\u011f\u0131l\u0131m\u0131 incelenmeli."});
      if(totalRatio>=.80)opportunities.push({code:"MARGIN",title:"K\u00e2r g\u00fcvenlik alan\u0131",level:totalRatio>=.95?"Y\u00dcKSEK":"ORTA",detail:"Sat\u0131n alma ve sabit gider toplam\u0131, cironun b\u00fcy\u00fck b\u00f6l\u00fcm\u00fcn\u00fc kullan\u0131yor. Detayl\u0131 COST analizi \u00f6nerilir."});
      else opportunities.push({code:"MARGIN_CONTROL",title:"K\u00e2r marj\u0131 do\u011frulamas\u0131",level:"D\u00dc\u015e\u00dcK",detail:"Genel g\u00f6r\u00fcn\u00fcm dengeli; fire, i\u015f\u00e7ilik ve de\u011fi\u015fken giderler eklenerek ger\u00e7ek k\u00e2r do\u011frulanmal\u0131d\u0131r."});
      if(opportunities.length<3)opportunities.push({code:"WASTE_CHECK",title:"Fire ve de\u011fi\u015fken gider kontrol\u00fc",level:"D\u00dc\u015e\u00dcK",detail:"\u00dc\u00e7 \u00f6zet rakam fireyi tek ba\u015f\u0131na g\u00f6stermez. Stok, porsiyon, i\u015f\u00e7ilik ve de\u011fi\u015fken giderler detayl\u0131 Check-Up ile do\u011frulanmal\u0131d\u0131r."});
      opportunities=opportunities.slice(0,3);
      return {success:true,release:"5.16.0",analysisId:radarId(),businessType:typeKey,businessTypeLabel:guide.label,
        ratios:{purchase:radarRound(purchaseRatio*100),fixed:radarRound(fixedRatio*100),combined:radarRound(totalRatio*100)},
        potential:{annualLow:radarRound(annualLow),annualMid:radarRound(annualMid),annualHigh:radarRound(annualHigh)},
        opportunities,
        disclaimer:"Bu sonu\u00e7, girilen \u00fc\u00e7 \u00f6zet veri ve muhafazak\u00e2r \u00f6n analiz varsay\u0131mlar\u0131na dayan\u0131r; kesin kazan\u00e7 veya tasarruf taahh\u00fcd\u00fc de\u011fildir. Stok, fire, i\u015f\u00e7ilik, vergi ve \u00fcr\u00fcn fiyatlar\u0131 incelenmeden kesin sonu\u00e7 verilemez."};
    }
    async function profitRadarAPI(request){
      try{const p=await request.json();return responseJSON({ok:true,result:calculateProfitRadarV5160(p)},200)}
      catch(e){return responseJSON({ok:false,error:"RADAR_INPUT_ERROR",message:String(e&&e.message||e)},400)}
    }

    function costRadarPage(){return "<!doctype html><html lang=\"tr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Gizli Kazan\u00e7 Radar\u0131 | Okyanus EDT</title><style>\n*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#eef5f3;color:#09283b}.top{position:sticky;top:0;z-index:5;background:#043b35;color:#fff;padding:14px 5%;display:flex;justify-content:space-between;gap:12px;align-items:center}.top a{color:#fff;text-decoration:none;font-weight:800}.wrap{max-width:1160px;margin:auto;padding:24px}.hero{background:linear-gradient(135deg,#043b35,#087a62);color:#fff;border-radius:18px;padding:30px}.hero h1{font-size:42px;margin:4px 0}.hero p{max-width:780px;line-height:1.55}.badge{display:inline-block;background:#ffffff22;border:1px solid #ffffff55;border-radius:999px;padding:7px 11px;font-size:12px;font-weight:900}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}.card{background:#fff;border:1px solid #d6e4e0;border-radius:15px;padding:20px;box-shadow:0 8px 24px #063a3020}.wide{grid-column:1/-1}.form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form label{font-size:13px;font-weight:900}.form input,.form select{width:100%;padding:12px;border:1px solid #bed2cd;border-radius:8px;font-size:16px;background:#fff}.btn{border:0;background:#087fe5;color:#fff;border-radius:9px;padding:13px 16px;font-weight:900;cursor:pointer}.btn.green{background:#087a62}.result{display:none}.result.show{display:block}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#f0faf7;border-radius:12px;padding:15px}.metric small{display:block;color:#55716a}.metric b{font-size:26px}.potential{background:#062f2b;color:#fff;border-radius:14px;padding:20px}.money{font-size:30px;font-weight:900}.opps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.opp{border:1px solid #d6e4e0;border-radius:12px;padding:14px}.level{display:inline-block;padding:5px 8px;border-radius:999px;background:#edf4f2;font-size:11px;font-weight:900}.note{background:#fff8e7;border-left:4px solid #dca51b;padding:13px;border-radius:8px;line-height:1.45}.check{background:#eaf8f4;border-left:4px solid #087a62;padding:14px;border-radius:9px}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions a{display:inline-block;text-decoration:none;background:#073b5e;color:#fff;border-radius:9px;padding:11px 14px;font-weight:900}@media(max-width:760px){.wrap{padding:12px}.grid,.form,.metrics,.opps{grid-template-columns:1fr}.wide{grid-column:auto}.hero h1{font-size:32px}.money{font-size:24px}}</style></head><body>\n<header class=\"top\"><b>OKYANUS EDT \u00b7 G\u0130ZL\u0130 KAZAN\u00c7 RADARI</b><span><a href=\"/\">\u2190 Ana Sayfa</a>\u3000<a href=\"/cost\">COST</a></span></header>\n<main class=\"wrap\"><section class=\"hero\"><span class=\"badge\">v5.16.0 MANTI\u011eI \u00b7 V2 WORKER</span><h1>Gizli Kazan\u00e7 Radar\u0131</h1><p>\u0130\u015fletmenizin \u00fc\u00e7 temel \u00f6zet verisini analiz ederek sat\u0131n alma, sabit gider ve k\u00e2r g\u00fcvenlik alanlar\u0131nda dikkat edilmesi gereken noktalar\u0131 g\u00f6r\u00fcn. Bu bir \u00f6n analizdir, kesin kazan\u00e7 taahh\u00fcd\u00fc de\u011fildir.</p></section>\n<section class=\"grid\"><article class=\"card\"><h2>1 \u00b7 \u0130\u015fletme Verileri</h2><form id=\"radarForm\" class=\"form\">\n<label>\u0130\u015fletme T\u00fcr\u00fc<select id=\"businessType\"><option value=\"RESTORAN\">Restoran</option><option value=\"KAFE\">Kafe</option><option value=\"OTEL\">Otel</option><option value=\"CATERING\">Catering / Yemekhane</option><option value=\"DIGER\">Di\u011fer HORECA</option></select></label>\n<label>Ayl\u0131k Ciro (TL)<input id=\"monthlyRevenue\" inputmode=\"decimal\" placeholder=\"\u00d6rn. 1.000.000\" required></label>\n<label>Ayl\u0131k Sat\u0131n Alma (TL)<input id=\"monthlyPurchase\" inputmode=\"decimal\" placeholder=\"\u00d6rn. 400.000\" required></label>\n<label>Ayl\u0131k Sabit Gider (TL)<input id=\"monthlyFixed\" inputmode=\"decimal\" placeholder=\"\u00d6rn. 300.000\" required></label>\n<button class=\"btn green wide\" type=\"submit\">Gizli Kazanc\u0131 Analiz Et</button></form><p id=\"status\"></p></article>\n<article class=\"card\"><h2>Nas\u0131l \u00c7al\u0131\u015f\u0131r?</h2><p>Radar, i\u015fletme t\u00fcr\u00fcn\u00fcze g\u00f6re sat\u0131n alma ve sabit gider oranlar\u0131n\u0131 rehber e\u015fiklerle kar\u015f\u0131la\u015ft\u0131r\u0131r. Muhafazak\u00e2r \u00f6n analizle potansiyel alan\u0131 hesaplar.</p><div class=\"check\"><b>Analiz ba\u015fl\u0131klar\u0131</b><p>Sat\u0131n alma oran\u0131 \u00b7 Sabit gider oran\u0131 \u00b7 Birle\u015fik gider oran\u0131 \u00b7 Y\u0131ll\u0131k potansiyel aral\u0131k \u00b7 En fazla 3 f\u0131rsat alan\u0131.</p></div><p>Detayl\u0131 do\u011frulama i\u00e7in stok, fire, i\u015f\u00e7ilik, vergi, \u00fcr\u00fcn fiyatlar\u0131 ve ger\u00e7ek re\u00e7ete COST'u ayr\u0131ca incelenmelidir.</p></article>\n<article id=\"result\" class=\"card wide result\"><h2>2 \u00b7 Radar Sonucu <small id=\"analysisId\"></small></h2><div class=\"metrics\"><div class=\"metric\"><small>Sat\u0131n Alma / Ciro</small><b id=\"purchaseRatio\">-</b></div><div class=\"metric\"><small>Sabit Gider / Ciro</small><b id=\"fixedRatio\">-</b></div><div class=\"metric\"><small>Toplam / Ciro</small><b id=\"combinedRatio\">-</b></div></div>\n<h2>3 \u00b7 Y\u0131ll\u0131k \u00d6n Potansiyel</h2><div class=\"potential\"><small>Alt tahmin</small><div id=\"low\" class=\"money\">-</div><small>Orta tahmin</small><div id=\"mid\" class=\"money\">-</div><small>\u00dcst tahmin</small><div id=\"high\" class=\"money\">-</div></div>\n<h2>4 \u00b7 \u00d6ncelikli F\u0131rsat Alanlar\u0131</h2><div id=\"opps\" class=\"opps\"></div><div id=\"disclaimer\" class=\"note\"></div>\n<h2>5 \u00b7 Sonraki Ad\u0131m</h2><div class=\"actions\"><a href=\"/cost\">Detayl\u0131 COST Analizi \u2192</a><a href=\"/urunler\">\u00dcr\u00fcn / Teklif \u00c7al\u0131\u015fmas\u0131 \u2192</a><a href=\"/iletisim\">\u00dccretsiz Check-Up \u0130\u00e7in \u0130leti\u015fim \u2192</a></div></article></section></main>\n<script>\nconst money=n=>new Intl.NumberFormat(\"tr-TR\",{style:\"currency\",currency:\"TRY\",maximumFractionDigits:0}).format(n||0);\nradarForm.onsubmit=async e=>{e.preventDefault();status.textContent=\"Analiz ediliyor...\";result.classList.remove(\"show\");let payload={businessType:businessType.value,monthlyRevenue:monthlyRevenue.value,monthlyPurchase:monthlyPurchase.value,monthlyFixed:monthlyFixed.value};try{let r=await fetch(\"/api/profit-radar\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok)throw new Error(j.message||\"Analiz yap\u0131lamad\u0131.\");let x=j.result;analysisId.textContent=\"\u00b7 \"+x.analysisId+\" \u00b7 \"+x.businessTypeLabel;purchaseRatio.textContent=x.ratios.purchase.toFixed(2)+\"%\";fixedRatio.textContent=x.ratios.fixed.toFixed(2)+\"%\";combinedRatio.textContent=x.ratios.combined.toFixed(2)+\"%\";low.textContent=money(x.potential.annualLow);mid.textContent=money(x.potential.annualMid);high.textContent=money(x.potential.annualHigh);opps.innerHTML=x.opportunities.map(o=>'<div class=\"opp\"><span class=\"level\">'+o.level+'</span><h3>'+o.title+'</h3><p>'+o.detail+'</p></div>').join(\"\");disclaimer.textContent=x.disclaimer;result.classList.add(\"show\");status.textContent=\"Analiz tamamland\u0131.\";localStorage.setItem(\"okyanusProfitRadarLast\",JSON.stringify({inputs:payload,result:x,date:new Date().toISOString()}));result.scrollIntoView({behavior:\"smooth\",block:\"start\"})}catch(err){status.textContent=err.message||\"Analiz yap\u0131lamad\u0131.\"}};\n</script></body></html>";}

