    function render(mode){
     detail.className="detail";detail.innerHTML="";tabs.forEach(t=>t.classList.toggle("on",t.dataset.mode===mode));
     const list=[...(mode==="blend"?blends:materials)].sort((a,b)=>a.name.localeCompare(b.name,"tr-TR",{usage:"sort",sensitivity:"base"}));count.textContent=list.length+" kay\u0131t";
     grid.className=mode==="blend"?"grid blends":"grid";grid.innerHTML=list.map(x=>'<button class="item" data-id="'+esc(x.id)+'">'+esc(x.name)+'</button>').join("");
     grid.querySelectorAll(".item").forEach(btn=>btn.onclick=()=>{
       grid.querySelectorAll(".item").forEach(x=>x.classList.remove("on"));btn.classList.add("on");
       const x=list.find(v=>v.id===btn.dataset.id);detail.innerHTML=mode==="blend"?blendCard(x):materialCard(x);detail.className="detail show";
       detail.querySelector(".close").onclick=()=>{detail.className="detail";btn.classList.remove("on")};
       detail.scrollIntoView({behavior:"smooth",block:"nearest"});
     });
    }
