function seoRouteLabel(path){return SEO_200_ROUTE_DATA[path]?.label||String(path||"").replace(/^\//,"").split("-").map(x=>x==="edt"?"EDT":x.charAt(0).toLocaleUpperCase("tr-TR")+x.slice(1)).join(" ")}
    function seoModulesHtml(items){
     const groups=["HORECA & \u0130\u015fletme","\u00dcr\u00fcn & Kategori","\u0130stanbul & Tedarik","EDT Rehberi"];
     // The reviewed route registry is authoritative: every known link appears once.
     const a=SEO_ROUTES.map((path,i)=>({path,label:seoRouteLabel(path),group_name:groups[Math.floor(i/50)]}));
     return '<section class="section seoGuide seoCompact" aria-label="EDT tedarik rehberi"><div class="sectionhead"><div><h2>EDT Tedarik Rehberi</h2><p>\u0130\u015fletmeniz i\u00e7in \u00fcr\u00fcn ve tedarik rehberlerini inceleyin.</p></div></div><div class="seoModules">'+groups.map((group,i)=>'<details class="seoModule"><summary>'+esc(group)+' <span>50 ba\u011flant\u0131</span></summary><nav aria-label="'+esc(group)+'">'+a.slice(i*50,(i+1)*50).map(x=>'<a href="'+esc(x.path)+'">'+esc(x.label)+'</a>').join('')+'</nav></details>').join('')+'</div></section>'
    }
    
function esc(v){return neutralCatalogText(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function money(v,currency="TRY"){const n=Number(v);if(!Number.isFinite(n)||n<=0)return "Fiyat i\u00e7in teklif al\u0131n";try{return new Intl.NumberFormat("tr-TR",{style:"currency",currency}).format(n)}catch{return n.toFixed(2)+" \u20ba"}}
function json(data,status=200){const raw=JSON.stringify(data),body=/kul[\s_-]*g[\u0131i]da|kulgida\.com/iu.test(raw)?JSON.stringify(neutralCatalogValue(data)):raw;return new Response(body,{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-okyanus-commerce":BUILD}})}
function html(body,status=200){return new Response(body,{status,headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-okyanus-commerce":BUILD}})}

