function help(){const cards=[["Nas\u0131l Sipari\u015f Verilir?","\u00dcr\u00fcn\u00fc bulun, miktar\u0131 belirleyin, Sepet/Teklif listenize ekleyin ve hesab\u0131n\u0131zdan tamamlay\u0131n."],["Nas\u0131l Teklif Al\u0131n\u0131r?","\u00dcr\u00fcn listenizi olu\u015fturun veya al\u0131\u015f listenizin foto\u011fraf\u0131n\u0131 g\u00f6nderin."],["Teslimat","Teslimat b\u00f6lgesi, minimum sipari\u015f ve sevkiyat bilgileri teklif/sipari\u015f a\u015famas\u0131nda do\u011frulan\u0131r."],["\u00dcyelik","Firma hesab\u0131n\u0131z teklif ge\u00e7mi\u015fi, adresler, favoriler ve firma \u00f6zel fiyatlar\u0131n\u0131 saklar."],["Fiyatlar","Liste, kampanya ve firma \u00f6zel fiyat\u0131 varsa uygun fiyat seviyesi g\u00f6sterilir."],["Kampanyalar","Aktif f\u0131rsatlar, \u00fcr\u00fcn indirimleri ve sepet kampanyalar\u0131 Kampanyalar alan\u0131nda g\u00f6r\u00fcn\u00fcr."],["\u0130ade","\u0130ade ko\u015fullar\u0131 \u00fcr\u00fcn grubu ve so\u011fuk zincir durumuna g\u00f6re de\u011ferlendirilir."],["Stok / Haber Ver","Stok d\u0131\u015f\u0131 \u00fcr\u00fcnler i\u00e7in haber verme \u00f6zelli\u011fi desteklenir."],["Sorun Bildir","\u0130leti\u015fim formundan mesaj\u0131n\u0131z do\u011frudan Okyanus y\u00f6netim merkezine ula\u015f\u0131r."]];const body=`<main class="wrap"><section class="page"><a class="homeReturn" href="/">\u2190 Ana Sayfa</a><h1>Site Yard\u0131m</h1><p>Sipari\u015ften teslimata kadar Okyanus EDT kullan\u0131m k\u0131lavuzu.</p><input id="helpSearch" type="search" placeholder="Yard\u0131m ara: sipari\u015f, fiyat, teslimat..." style="width:100%;min-height:46px;border:1px solid #bfd3e1;border-radius:11px;padding:0 14px;margin:8px 0 14px"><div id="default-help" class="helpgrid">${cards.map(x=>`<article class="help helpItem"><b>${x[0]}</b><span>${x[1]}</span></article>`).join("")}</div><div id="managed-help" class="helpgrid" style="margin-top:10px"></div><p style="margin-top:20px"><a class="btn" style="background:#0768b2;color:white" href="/iletisim">\u00c7\u00f6zemedim, \u0130leti\u015fime Ge\u00e7</a></p></section></main>`;const script=`(function(){const q=document.getElementById('helpSearch');function filter(){const v=String(q?.value||'').toLocaleLowerCase('tr-TR');document.querySelectorAll('.helpItem').forEach(x=>x.hidden=!!v&&!x.textContent.toLocaleLowerCase('tr-TR').includes(v))}if(q)q.oninput=filter;fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=Array.isArray(j.help)?j.help:[],el=document.getElementById('managed-help');if(el&&a.length){el.innerHTML=a.map(x=>'<article class="help helpItem"><b>'+String(x.title||'Yard\u0131m').replace(/[&<>]/g,'')+'</b><span>'+String(x.body||'').replace(/[&<>]/g,'')+'</span></article>').join('');filter()}}).catch(()=>{})})();`;return commerceClientShell('Site Yard\u0131m | Okyanus EDT',body,script)}

function contact(){return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" type="image/png" sizes="32x32" href="https://raw.githubusercontent.com/hasankaya474-a11y/isletme-sepeti-platform/44ddd3bf4e9ae57bf35056ae30696329b8d6c51e/okyonus-edt-worker/releases/r38/assets/695b2b53078660490bc88cebebe87ba0c10a9f8d25cef1a0dee00cc2c82673fd.png?v=37"><link rel="icon" href="https://raw.githubusercontent.com/hasankaya474-a11y/isletme-sepeti-platform/44ddd3bf4e9ae57bf35056ae30696329b8d6c51e/okyonus-edt-worker/releases/r38/assets/2c8fbf4e4a065d27140e7d3e21b0f540fb71b0585865fc972d31bb4ffdc79b90.ico?v=37" sizes="any"><link rel="apple-touch-icon" sizes="180x180" href="https://raw.githubusercontent.com/hasankaya474-a11y/isletme-sepeti-platform/44ddd3bf4e9ae57bf35056ae30696329b8d6c51e/okyonus-edt-worker/releases/r38/assets/c056518f2347359acd475bb06ac0058ed1681af2984e1c91dc6244fee01ccdc1.png?v=37"><meta name="theme-color" content="#07345e"><meta name="viewport" content="width=device-width,initial-scale=1"><title>\u0130leti\u015fim | Okyanus EDT</title><style>'+css()+'</style></head><body>'+header()+'<main class="wrap"><a class="homeReturn" href="/">\u2190 Ana Sayfa</a><section class="page"><h1>\u0130leti\u015fim</h1><div class="contactgrid"><div class="salesTeam" id="sales-team"><article class="salesPerson"><h3 data-contact-name>'+esc(DEFAULT_SETTINGS.contactName)+'</h3><p>Sat\u0131\u015f ve i\u015f geli\u015ftirme</p><div class="personActions"><a id="contactPhone1Page" href="tel:+905323469925">\u260e '+esc(DEFAULT_SETTINGS.phone)+'</a><a class="waLink" id="contactWhatsapp1Page" target="_blank" rel="noopener" href="https://api.whatsapp.com/send?phone=905323469925">WhatsApp</a></div></article><article class="salesPerson"><h3 data-contact-name-2>'+esc(DEFAULT_SETTINGS.secondContactName)+'</h3><p>Sat\u0131\u015f ve m\u00fc\u015fteri ileti\u015fimi</p><div class="personActions"><a id="contactPhone2Page" href="tel:+905358813264">\u260e '+esc(DEFAULT_SETTINGS.secondPhone)+'</a><a class="waLink" id="contactWhatsapp2Page" target="_blank" rel="noopener" href="https://api.whatsapp.com/send?phone=905358813264">WhatsApp</a></div></article><article class="salesPerson"><h3>Merkez \u0130leti\u015fim</h3><p>\u00dcr\u00fcn, fiyat, teslimat, teklif ve i\u015f birli\u011fi i\u00e7in bize ula\u015f\u0131n.</p><div class="personActions"><a id="contactEmail" href="mailto:'+esc(DEFAULT_SETTINGS.email)+'">\u2709 '+esc(DEFAULT_SETTINGS.email)+'</a><a data-admin-link class="adminLink" href="/yonetici">\ud83d\udd12 Y\u00f6netici Paneli</a></div><p id="contactAddress">'+esc(DEFAULT_SETTINGS.address)+'</p></article></div><form id="contactForm" class="form"><input name="name" required placeholder="Ad Soyad"><input name="business" placeholder="\u0130\u015fletme / Firma"><input name="phone" required placeholder="Telefon"><input name="email" type="email" placeholder="E-posta"><textarea name="message" required placeholder="Mesaj\u0131n\u0131z"></textarea><label><input name="consent" type="checkbox" required style="width:auto"> <a href="/kvkk" target="_blank" rel="noopener">KVKK Ayd\u0131nlatma Metni</a>ni okudum.</label><button>Mesaj\u0131 G\u00f6nder</button><div id="contactResult" role="status"></div></form></div></section>'+contactStrip()+'</main>'+footer()+mobile()+'<script>let contactSending=false;contactForm.onsubmit=async e=>{e.preventDefault();if(contactSending)return;const submit=contactForm.querySelector("button[type=submit],button:not([type])");contactSending=true;if(submit)submit.disabled=true;const f=Object.fromEntries(new FormData(contactForm));contactResult.textContent="G\u00f6nderiliyor...";try{const r=await fetch("/api/contact",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(f)}),j=await r.json();contactResult.textContent=r.ok&&j.ok!==false?"Mesaj\u0131n\u0131z al\u0131nd\u0131.":(j.message||j.error||"Mesaj g\u00f6nderilemedi.")}catch(_){contactResult.textContent="Ba\u011flant\u0131 hatas\u0131. Bilgileriniz korunuyor; tekrar deneyebilirsiniz."}finally{contactSending=false;if(submit)submit.disabled=false}}</script><script>'+cartRuntimeScript()+'</script><script>'+favoriteRuntimeScript()+'</script>'+runtimeSettingsScript()+'</body></html>'}
function studio(){const mods=[["Dijital Men\u00fc","/dijital-menu","Men\u00fc tema, \u015fablon ve yay\u0131n ara\u00e7lar\u0131."],["Foto\u011frafla Teklif","/fotografla-teklif","Al\u0131\u015f listesini foto\u011frafla g\u00f6nder."],["\u00c7E\u015eN\u0130","/cesni","\u00dcr\u00fcn geli\u015ftirme / AR-GE ara\u00e7lar\u0131."],["COST","/cost","Maliyet ara\u00e7lar\u0131."],["Akademi","/akademi","E\u011fitim ve i\u00e7erik ara\u00e7lar\u0131."],["Kolay Re\u00e7ete","/kolay-recete","Mutfak re\u00e7ete ara\u00e7lar\u0131."]];const body=`<main class="wrap"><section class="page"><a class="homeReturn" href="/">\u2190 Ana Sayfa</a><h1>\u0130\u00e7erik St\u00fcdyo</h1><p>Al\u0131\u015fveri\u015f ak\u0131\u015f\u0131ndan ayr\u0131 tutulan Okyanus yard\u0131mc\u0131 ara\u00e7lar\u0131.</p><div class="helpgrid">${mods.map(x=>`<a class="help" href="${x[1]}"><b>${x[0]}</b><span>${x[2]}</span></a>`).join("")}</div></section></main>`;return commerceClientShell('\u0130\u00e7erik St\u00fcdyo | Okyanus EDT',body,'')}

async function newsletterApi(request,env){
 const DB=commerceDatabase(env);if(!DB)return json({ok:false,error:"DB_NOT_BOUND"},503);
 if(request.method!=="POST")return json({ok:false,error:"METHOD_NOT_ALLOWED"},405);
 let b={};try{b=await request.json()}catch{return json({ok:false,error:"INVALID_JSON"},400)}
 const email=String(b.email||"").trim().toLowerCase(),name=String(b.name||"").trim().slice(0,120);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return json({ok:false,error:"INVALID_EMAIL"},400);if(b.consent!==true)return json({ok:false,error:"CONSENT_REQUIRED"},400);
 try{const has=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_newsletter_subscribers_v1'").first();if(!has)return json({ok:false,error:"NEWSLETTER_NOT_READY"},503);await DB.prepare("INSERT INTO oky_newsletter_subscribers_v1(id,email,name,consent_version,status,created_at,updated_at) VALUES(?,?,?,?, 'ACTIVE',datetime('now'),datetime('now')) ON CONFLICT(email) DO UPDATE SET name=excluded.name,consent_version=excluded.consent_version,status='ACTIVE',updated_at=datetime('now')").bind(crypto.randomUUID(),email,name||null,"2026-09-30-newsletter").run();return json({ok:true,status:"ACTIVE"},201)}catch{return json({ok:false,error:"NEWSLETTER_SAVE_FAILED"},500)}
}

async function storefront(env){
 const storefrontDB=commerceDatabase(env);
 let products=[],catalogAuthoritative=false,homepageAuthoritative=false,catalogReadError=false;
 try{
  const DB=storefrontDB;
  if(DB){
   const has=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='b2b_products_v1'").first();
   if(has){
    const total=await DB.prepare("SELECT COUNT(*) n FROM b2b_products_v1").first();
    catalogAuthoritative=Number(total?.n||0)>0;
    const hasMeta=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_product_meta_v1'").first();
    const hasCommerce=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_product_commerce_v1'").first();
    const columns=async table=>new Set(((await DB.prepare('PRAGMA table_info('+table+')').all()).results||[]).map(c=>c.name));
    const pCols=await columns('b2b_products_v1'),mCols=hasMeta?await columns('oky_product_meta_v1'):new Set(),cCols=hasCommerce?await columns('oky_product_commerce_v1'):new Set();
    const pick=(cols,alias,name,fallback='NULL',label=name)=> (cols.has(name)?alias+'.'+name:fallback)+' AS '+label;
    const hasBrands=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_brands_v1'").first();
    const hasPrices=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='b2b_prices_v1'").first();
    const brandCols=hasBrands?await columns('oky_brands_v1'):new Set(),priceCols=hasPrices?await columns('b2b_prices_v1'):new Set();
    const metaCols=','+['description','seo_title','seo_description','featured','sort_order','brand_id'].map(n=>pick(mCols,'m',n,['featured','sort_order'].includes(n)?'0':'NULL')).join(',')+','+(mCols.has('brand_id')&&brandCols.has('id')&&brandCols.has('name')?'(SELECT name FROM oky_brands_v1 b WHERE b.id=m.brand_id'+(brandCols.has('active')?' AND b.active=1':'')+' LIMIT 1)':'NULL')+' AS brand';
    const commerceCols=','+['sku','barcode','subcategory','origin','storage_conditions','cold_chain','min_order_qty','qty_step','list_price','sale_price','new_until','best_seller'].map(n=>pick(cCols,'pc',n,['min_order_qty','qty_step'].includes(n)?'1':['cold_chain','best_seller'].includes(n)?'0':'NULL')).join(',');
    const joins=(hasMeta?" LEFT JOIN oky_product_meta_v1 m ON m.product_id=p.id":"")+(hasCommerce?" LEFT JOIN oky_product_commerce_v1 pc ON pc.product_id=p.id":"");
    const order=(mCols.has('featured')?"COALESCE(m.featured,0) DESC,":"")+(cCols.has('best_seller')?"COALESCE(pc.best_seller,0) DESC,":"")+(mCols.has('sort_order')?"COALESCE(m.sort_order,0),":"")+(pCols.has('updated_at')?'p.updated_at DESC':'p.id');
    const priceExpr=priceCols.has('product_id')&&priceCols.has('price')?"(SELECT price FROM b2b_prices_v1 pr WHERE pr.product_id=p.id"+(priceCols.has('active')?' AND pr.active=1':'')+(priceCols.has('valid_until')?" AND (pr.valid_until IS NULL OR pr.valid_until>datetime('now'))":"")+(priceCols.has('valid_from')?" AND (pr.valid_from IS NULL OR pr.valid_from<=datetime('now')) ORDER BY pr.valid_from DESC":'')+' LIMIT 1)':'NULL';
    const sql='SELECT '+['id','source_product_id','name','category','unit','package_text','image_url','stock_status','active'].map(n=>pick(pCols,'p',n,n==='active'?'1':'NULL',n==='image_url'?'image':n)).join(',')+','+priceExpr+' AS basePrice'+metaCols+commerceCols+' FROM b2b_products_v1 p'+joins+(pCols.has('active')?' WHERE p.active=1':'')+' ORDER BY '+order;
    const rows=(await DB.prepare(sql).all()).results||[];homepageAuthoritative=!!hasMeta&&mCols.has("featured");
    products=rows.map(x=>{const sale=Number(x.sale_price),base=Number(x.basePrice),list=Number(x.list_price);const saleOk=x.sale_price!=null&&x.sale_price!==""&&Number.isFinite(sale)&&sale>=0;const baseOk=x.basePrice!=null&&x.basePrice!==""&&Number.isFinite(base)&&base>=0;const listOk=x.list_price!=null&&x.list_price!==""&&Number.isFinite(list)&&list>=0;const effectivePrice=saleOk?sale:(baseOk?base:(listOk?list:null));const listPrice=listOk?list:(saleOk&&baseOk&&base>sale?base:null);const discountPercent=listPrice!=null&&effectivePrice!=null&&listPrice>effectivePrice?Math.round((1-effectivePrice/listPrice)*100):0;return {...x,effectivePrice,listPrice,discountPercent}});
   }
  }
 }catch{catalogReadError=true;homepageAuthoritative=false;products=[];}
 let banners=[],categories=[],sections=[],campaigns=[],campaignRules=[],brands=[],delivery=[],helpArticles=[],seoLinks=[],settings={};
 try{
  const DB=storefrontDB;
  if(DB){
   const hb=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_banners_v1'").first();
   if(hb)banners=(await DB.prepare("SELECT * FROM oky_storefront_banners_v1 WHERE active=1 AND (start_at IS NULL OR start_at<=datetime('now')) AND (end_at IS NULL OR end_at>=datetime('now')) ORDER BY sort_order,rowid").all()).results||[];
   const hc=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_categories_v1'").first();
   if(hc)categories=(await DB.prepare("SELECT * FROM oky_storefront_categories_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 30").all()).results||[];
   const hs=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_sections_v1'").first();
   if(hs)sections=(await DB.prepare("SELECT * FROM oky_storefront_sections_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 30").all()).results||[];
   const hcamp=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_campaigns_v1'").first();
   if(hcamp)campaigns=(await DB.prepare("SELECT * FROM oky_campaigns_v1 WHERE active=1 AND (start_at IS NULL OR start_at<=datetime('now')) AND (end_at IS NULL OR end_at>=datetime('now')) ORDER BY priority DESC,sort_order,rowid LIMIT 10").all()).results||[];
   const hcr=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_campaign_rules_v1'").first();
   if(hcr&&hcamp)campaignRules=(await DB.prepare("SELECT r.* FROM oky_campaign_rules_v1 r JOIN oky_campaigns_v1 c ON c.id=r.campaign_id WHERE r.active=1 AND c.active=1 AND (c.start_at IS NULL OR c.start_at<=datetime('now')) AND (c.end_at IS NULL OR c.end_at>=datetime('now')) ORDER BY c.priority DESC,r.sort_order,r.rowid LIMIT 100").all()).results||[];
   const hbrand=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_brands_v1'").first();
   if(hbrand)brands=(await DB.prepare("SELECT * FROM oky_brands_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hdel=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_delivery_rules_v1'").first();
   if(hdel)delivery=(await DB.prepare("SELECT * FROM oky_delivery_rules_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hhelp=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_help_articles_v1'").first();
   if(hhelp)helpArticles=(await DB.prepare("SELECT * FROM oky_help_articles_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hset=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_settings_v1'").first();
   if(hset){const sr=(await DB.prepare("SELECT key,value FROM oky_storefront_settings_v1").all()).results||[];settings=Object.fromEntries(sr.map(x=>[x.key,x.value]));}
   const hseo=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_seo_links_v1'").first();
   if(hseo)seoLinks=(await DB.prepare("SELECT path,label,group_name,sort_order FROM oky_seo_links_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 200").all()).results||[];
  }
 }catch{}
 if(products.length&&campaignRules.length){products=products.map(p=>{let price=Number(p.effectivePrice),list=Number(p.listPrice),campaignLabel="";if(p.effectivePrice==null||!Number.isFinite(price))return p;for(const r of campaignRules){const type=String(r.target_type||"PRODUCT").toUpperCase(),target=String(r.target_value||"").toLocaleLowerCase("tr-TR"),match=type==="ALL"||(type==="PRODUCT"&&[p.id,p.source_product_id,p.sku,p.name].some(x=>String(x||"").toLocaleLowerCase("tr-TR")===target))||(type==="CATEGORY"&&String(p.category||"").toLocaleLowerCase("tr-TR")===target)||(type==="BRAND"&&String(p.brand||"").toLocaleLowerCase("tr-TR")===target);if(!match||Number(r.min_cart||0)>0)continue;const d=Number(r.discount_value||0);if(!Number.isFinite(d)||d<=0)continue;const next=String(r.discount_type||"PERCENT").toUpperCase()==="FIXED"?Math.max(0,price-d):Math.max(0,price*(1-Math.min(100,d)/100));if(next<price){if(!Number.isFinite(list)||list<=price)list=price;price=next;campaignLabel=String(r.campaign_type||"Kampanya")}if(Number(r.combinable)!==1)break}const discountPercent=Number.isFinite(list)&&list>price?Math.round((1-price/list)*100):Number(p.discountPercent||0);return {...p,effectivePrice:price,listPrice:Number.isFinite(list)?list:p.listPrice,discountPercent,campaignLabel}});}
 const seedSeen=new Set(products.map(p=>String(p.source_product_id||p.id||p.name||"").toLocaleLowerCase("tr-TR")));for(const seed of (catalogAuthoritative?[]:FALLBACK_PRODUCTS)){const k=String(seed.source_product_id||seed.id||seed.name||"").toLocaleLowerCase("tr-TR");if(!seedSeen.has(k)){seedSeen.add(k);products.push(seed)}}
 const defaultCategories=[["Deniz \u00dcr\u00fcnleri","deniz-urunleri","\ud83d\udc1f"],["Donuk \u00dcr\u00fcnler","donuk-urunler","\u2744"],["Et & \u015eark\u00fcteri","et-sarkuteri","\ud83e\udd69"],["S\u00fct & \u015eark\u00fcteri","sut-sarkuteri","\ud83e\uddc0"],["Ya\u011flar","yaglar","\ud83e\uded7"],["Soslar","soslar","\ud83e\udd6b"],["Kuru G\u0131da","kuru-gida","\ud83c\udf3e"],["Baharat","baharat","\u2726"]];const catSeen=new Set(categories.map(c=>String(c.slug||"").toLocaleLowerCase("tr-TR")));categories=categories.map(c=>{const slugKey=String(c.slug||"").toLocaleLowerCase("tr-TR"),currentImage=String(c.image_url||"");const legacyCategoryImage=/\/assets\/storefront\/cat-(deniz|donuk|et|sut|yag|sos|kuru|baharat)\.svg(?:\?|$)/.test(currentImage);return {...c,image_url:(!currentImage||legacyCategoryImage)?(CATEGORY_VISUALS[slugKey]||currentImage):currentImage}});for(let i=0;i<defaultCategories.length;i++){const [name,slug,icon]=defaultCategories[i];if(!catSeen.has(slug))categories.push({id:"fallback-"+slug,name,slug,icon,image_url:CATEGORY_VISUALS[slug]||"",sort_order:i,active:1})}
 return json({ok:true,build:BUILD,catalogAuthoritative,homepageAuthoritative,catalogReadError,products:products.map(p=>{const resolved={...p,image:commerceProductImage(p)};return resolved}),banners,categories,sections,campaigns,campaignRules,brands,delivery,help:helpArticles,seo:seoLinks,settings:publicStorefrontSettings(settings),legacyCatalogEndpoint:"/api/products"});
}


