          if ((request.method === "GET" || request.method === "HEAD") && url.hostname === "okyonusedt.com") {
            const target = new URL(request.url);
            target.protocol = "https:";
            target.hostname = "www.okyonusedt.com";
            if (target.pathname.length > 1 && target.pathname.endsWith("/")) target.pathname = target.pathname.slice(0,-1);
            return new Response(null,{status:301,headers:{location:target.toString(),"cache-control":"public, max-age=3600","x-okyanus-seo-build":CONFIG.buildId}});
          }
          if ((request.method === "GET" || request.method === "HEAD") && url.pathname.length > 1 && url.pathname.endsWith("/")) {
            const target = new URL(request.url);
            target.pathname = target.pathname.slice(0,-1);
            return new Response(null,{status:301,headers:{location:target.toString(),"cache-control":"public, max-age=3600","x-okyanus-seo-build":CONFIG.buildId}});
          }

          let path =
            url.pathname;

          if (
            path.length > 1 &&
            path.endsWith("/")
          ) {
            path =
              path.slice(0, -1);
          }

          // Commerce V20 owns the public storefront routes while legacy engines remain intact.
          const commerceResponse = await commerceRoute(request, env);
          if (commerceResponse) {
                if((commerceResponse.headers.get("content-type")||"").includes("text/html")){
                  let content=await commerceResponse.text();
                  const canonical="https://www.okyonusedt.com"+path;
                  const privatePage=/^\/(?:uye|sepet|hesabim|yonetici|admin)(?:\/|$)/.test(path);
                  const escapeHead=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
                  const title=(content.match(/<title>([^<]*)<\/title>/i)||[])[1]||"Okyanus EDT";
                  const description=(content.match(/<meta name="description" content="([^"]*)"/i)||[])[1]||"Okyanus EDT profesyonel \u00fcr\u00fcn katalo\u011fu ve teklif hizmeti.";
                  const metadata='<link rel="canonical" href="'+escapeHead(canonical)+'"><meta name="robots" content="'+(privatePage?'noindex,nofollow':'index,follow,max-image-preview:large')+'"><meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="Okyanus EDT"><meta property="og:title" content="'+title+'"><meta property="og:description" content="'+description+'"><meta property="og:url" content="'+escapeHead(canonical)+'">';
                  content=content.replace('</head>',metadata+(path==='/'?'<script type="application/ld+json">'+JSON.stringify({"@context":"https://schema.org","@type":"WebSite","name":"Okyanus EDT","url":"https://www.okyonusedt.com/","inLanguage":"tr-TR"})+'</script>':'')+'</head>');
                  const headers=new Headers(commerceResponse.headers);headers.delete('content-length');if(privatePage)headers.set('x-robots-tag','noindex, nofollow');
                  return new Response(content,{status:commerceResponse.status,headers});
                }
                return commerceResponse;
              }

          if(path==="/api/member/activity")return await memberActivityAPI(request,env);
          if(path==="/api/member/quote-history"&&request.method==="GET")return await memberCustomerQuoteHistory(request,env);
          if(request.method==="POST"&&(path==="/api/quote"||path==="/api/photo-inquiries"||path==="/api/b2b/quotes"||/^\/api\/b2b\/quotes\/[^/]+\/repeat$/.test(path))){
            const customer=await memberSession(request,env);
            if(!customer)return memberJSON({ok:false,error:"UNAUTHENTICATED",message:"Teklif veya sipari\u015f g\u00f6ndermek i\u00e7in \u00fcye olun ya da giri\u015f yap\u0131n.",loginUrl:"/uye?next=%2Fsepet"},401);
          }
          // \u00dcr\u00fcn se\u00e7imi, COST Radar ve foto\u011fraf talebi a\u00e7\u0131k; i\u015f ara\u00e7lar\u0131 hesap gerektirir.
          const memberToolAPI=path==="/api/cost/records"||path.startsWith("/api/cesni/")||path.startsWith("/api/digital-menu/")||path==="/api/member/recipes"||path==="/api/member/digital-menus"||path==="/digital-menu-app.js";
          if(memberToolAPI){
            if(!memberPortalEnabled(env))return memberJSON({ok:false,error:"MEMBER_PORTAL_DISABLED"},503);
            const toolMember=await memberSession(request,env);
            if(!toolMember)return memberJSON({ok:false,error:"UNAUTHENTICATED",message:"Bu ara\u00e7 i\u00e7in i\u015fletme hesab\u0131n\u0131za giri\u015f yap\u0131n."},401);
            const expectedBusiness=request.headers.get("x-okyanus-business");if(!expectedBusiness&&(path==="/api/cost/records"||path==="/api/member/recipes"||path==="/api/member/digital-menus"||path.startsWith("/api/digital-menu/")))return memberJSON({ok:false,error:"BUSINESS_SCOPE_REQUIRED",message:"\u0130\u015fletme sayfas\u0131n\u0131 yeniden a\u00e7\u0131n."},400);if(expectedBusiness&&expectedBusiness!==toolMember.business_id)return memberJSON({ok:false,error:"BUSINESS_SESSION_CHANGED",message:"\u0130\u015fletme oturumu de\u011fi\u015fti. Bu sayfay\u0131 yeniden a\u00e7\u0131n."},409);
          }

          const visitCookies=memberCookies(request),visitToken=/^[a-f0-9-]{36}$/i.test(visitCookies.oky_notice_visit_v2||"")?visitCookies.oky_notice_visit_v2:crypto.randomUUID();
          // v1.28 HARD MEMBER GATE: fail closed before any private page/API renderer.
