function neutralCatalogValue(value) {
 if(typeof value === "string")return neutralCatalogText(value);
 if(Array.isArray(value))return value.map(neutralCatalogValue);
 if(value&&typeof value === "object")return Object.fromEntries(Object.entries(value).map(([key,item])=>[key,neutralCatalogValue(item)]));
 return value;
}
function neutralCatalogText(value) {
 const text=String(value);if(!/kul[\s_-]*g[\u0131i]da|kulgida\.com/iu.test(text))return text;return text.replace(/https?:\/\/kulgida\.com(?:\/[^\s"<>]*)?/giu, "").replace(/kul[\s_-]*g[\u0131i]da/giu, "");
}

