// Compatibility URLs redirect to the exact original image bytes stored separately.
function okyEmbeddedAsset(request){
 const path=new URL(request.url).pathname,url=OKY_STATIC_ASSET_URLS[path];
 if(!url){if(path.startsWith('/assets/oky-embedded-r36/'))return new Response('Not found',{status:404});return null;}
 if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{allow:'GET, HEAD'}});
 return new Response(null,{status:302,headers:{location:url,'cache-control':'public, max-age=300','x-content-type-options':'nosniff'}});
}

const okyR40InnerWorker = {
 async fetch(request, env, ctx) {
  const inputType=request.headers.get("content-type")||"";
  const incomingPath=new URL(request.url).pathname;const sensitive=/login|logout|password|session|auth|register|csrf/i.test(incomingPath);
  const embedded=okyEmbeddedAsset(request);if(embedded)return embedded;
  if(!sensitive&&!["GET","HEAD"].includes(request.method)&&/application\/json|application\/x-www-form-urlencoded/i.test(inputType)){
   const original=await request.clone().text();let clean=neutralCatalogText(original);
   if(/application\/x-www-form-urlencoded/i.test(inputType)){const form=new URLSearchParams(original);for(const [key,value]of form)form.set(key,neutralCatalogText(value));clean=form.toString();}
   if(/application\/json/i.test(inputType)){try{clean=JSON.stringify(neutralCatalogValue(JSON.parse(original)))}catch{}}
   if(clean!==original){const headers=new Headers(request.headers);headers.delete("content-length");request=new Request(request,{headers,body:clean});}
  }
  const response=await denizWorker.fetch(request,env,ctx),type=response.headers.get("content-type")||"";
  if(request.method==="HEAD")return new Response(null,{status:response.status,statusText:response.statusText,headers:response.headers});
  if(sensitive)return response;
  if(!response.body||!/application\/json|text\/html|text\/plain/i.test(type))return response;
  if(response.headers.has("x-okyanus-commerce"))return response;
  const original=await response.text();let clean=neutralCatalogText(original);
  if(clean!==original&&/application\/json/i.test(type)){try{clean=JSON.stringify(neutralCatalogValue(JSON.parse(original)))}catch{}}
  const headers=new Headers(response.headers);headers.delete("content-length");
  return new Response(clean,{status:response.status,statusText:response.statusText,headers});
 },
 scheduled(event,env,ctx){return denizWorker.scheduled(event,env,ctx)}
};

 function serviceStatusScript(){return `<script>(function(){var e=document.getElementById('okyServiceStatus');if(!e)return;var busy=false;async function check(){if(busy)return;if(!navigator.onLine){e.textContent='\u0130nternet ba\u011flant\u0131s\u0131 yok';return}busy=true;var c=new AbortController(),t=setTimeout(function(){c.abort()},8000);try{var r=await fetch('/api/health',{cache:'no-store',headers:{accept:'application/json'},signal:c.signal}),j=await r.json();if(!r.ok||j.ok!==true)throw Error('health');e.textContent='Site \u00e7evrimi\u00e7i \u00b7 Kontrol '+new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'});e.title='Site sunucusuna ba\u011flant\u0131 do\u011fruland\u0131. Bu g\u00f6sterge sat\u0131\u015f ekibinin \u00e7evrimi\u00e7i oldu\u011funu belirtmez.'}catch(_){e.textContent=navigator.onLine?'Site ba\u011flant\u0131s\u0131 do\u011frulanamad\u0131':'\u0130nternet ba\u011flant\u0131s\u0131 yok'}finally{clearTimeout(t);busy=false}}check();addEventListener('online',check);addEventListener('offline',function(){e.textContent='\u0130nternet ba\u011flant\u0131s\u0131 yok'});document.addEventListener('visibilitychange',function(){if(!document.hidden)check()});setInterval(function(){if(!document.hidden)check()},60000)})();</script>`}

// R40 response hardening; report-only script policy preserves existing inline modules.
function okyR40SecureResponse(request,response,admin=false){
 if(response.status===101)return response;
 const headers=new Headers(response.headers),path=new URL(request.url).pathname;
 headers.set('strict-transport-security','max-age=31536000');
 headers.set('x-content-type-options','nosniff');
 headers.set('x-frame-options','DENY');
 headers.set('referrer-policy','strict-origin-when-cross-origin');
 headers.set('permissions-policy','camera=(self), microphone=(), geolocation=()');
 // Enforce narrow structural rules; script restrictions are observation-only pending nonce migration.
 headers.set('content-security-policy',"base-uri 'self'; object-src 'none'; frame-ancestors 'none'");
 headers.set('content-security-policy-report-only',"default-src 'self' https:; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https: data: blob:; connect-src 'self' https:; font-src 'self' https: data:; worker-src 'self' blob:");
 if(admin||request.headers.has('authorization')||request.headers.has('cookie')||headers.has('set-cookie')||/^\/(?:api\/(?:member|auth|admin)|uye|hesabim|yonetici)(?:\/|$)/.test(path)){
  headers.set('cache-control','private, no-store');
  headers.delete('expires');headers.delete('etag');
  const vary=headers.get('vary');if(vary!=='*')headers.set('vary',[vary,'Cookie','Authorization'].filter(Boolean).join(', '));
 }
 return new Response(request.method==='HEAD'?null:response.body,{status:response.status,statusText:response.statusText,headers});
}

export default {
 async fetch(request,env,ctx){
  if(new URL(request.url).pathname==='/api/health'){
   const allowed=request.method==='GET'||request.method==='HEAD';
   const response=new Response(allowed?JSON.stringify({ok:true,service:'okyanus-edt-web',checkedAt:new Date().toISOString(),scope:'web-worker'}):JSON.stringify({ok:false,error:'METHOD_NOT_ALLOWED'}),{status:allowed?200:405,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','allow':'GET, HEAD','x-robots-tag':'noindex'}});
   return okyR40SecureResponse(request,response);
  }

  return okyR40SecureResponse(request,await okyR40InnerWorker.fetch(request,env,ctx),false);
 },
 scheduled(event,env,ctx){return okyR40InnerWorker.scheduled?.(event,env,ctx)}
};
